<?php
require_once __DIR__.'/../src/Database.php';require_once __DIR__.'/../src/Finance.php';require_once __DIR__.'/../src/Repository.php';
$db=Database::connection();$db->beginTransaction();try{$loan=$db->query('SELECT id,status FROM loans ORDER BY id LIMIT 1')->fetch();if(!$loan){echo "SKIP no hay préstamos de prueba\n";$db->rollBack();exit(0);} $r=new Repository($db);$list=$r->loans();if(!$list)throw new RuntimeException('no lista préstamos');$r->cancelLoan((int)$loan['id']);$s=$db->prepare('SELECT status FROM loans WHERE id=?');$s->execute([$loan['id']]);if($s->fetchColumn()!=='cancelled' && $loan['status']!=='paid')throw new RuntimeException('cancelación inválida');$db->rollBack();echo "PASS estados y filtro de préstamos\n";}catch(Throwable $e){$db->rollBack();fwrite(STDERR,'FAIL loans: '.$e->getMessage().PHP_EOL);exit(1);}
